command:
await Requestor.request({
  img: "icons/environment/people/infantry-army.webp",
  title: "É GUERRA!!!",
  description: "Role um EVENTO!",
   buttonData: [{
    label: "Role um EVENTO",
    command: async ()=> {

const title = "É GUERRA!";
const description = "Role um Evento";

const buttonNames = [
  'Eventos de Batalha (Acampamento)',
  'Eventos de Batalha (Retaguarda)',
  'Eventos de Batalha (Front)',
  'Eventos de Batalha (Atrás das Linhas)',
];

let content = `
  <script>
  function rollTable(i) {
    const tables = [
      'Eventos de Batalha (Acampamento)',
      'Eventos de Batalha (Atrás das Linhas)',
      'Eventos de Batalha (Front)',
      'Eventos de Batalha (Retaguarda)',
    ];
    const table = game.tables.getName(tables[i]);
    if (table == null) {
      ui.notifications.warn("Table not found");
      return;
    }
    table.draw({rollMode:"roll"});
  }
  </script>
  ${description}
  <div style="display: flex; flex-wrap: wrap;">`;

// Coluna 1
content += '<div style="flex: 1;">';
for (let i = 0; i < buttonNames.length; i++) {
  content += `<button onclick="rollTable(${i})">${buttonNames[i]}</button><br>`;
}
content += '</div>';

new Dialog({
  title: title,
  content: content,
  buttons: { close: { label: "Fechar" } 
  }
}).render(true);
table.draw()
    }
  }]
});
